parameters.jsCode:
// Parse Groq response for lead scoring
const groqResponse = $json;
const content = groqResponse.choices?.[0]?.message?.content || '{}';

// Extract JSON from response
let parsed;
try {
  // Try to find JSON in the response
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  // Fallback parsing if AI response is malformed
  const scoreMatch = content.match(/lead_score['"\s:]+(\d+)/i);
  const priorityMatch = content.match(/priority['"\s:]+['"]?(hot|warm|cold)/i);
  parsed = {
    lead_score: scoreMatch ? parseInt(scoreMatch[1]) : 50,
    priority: priorityMatch ? priorityMatch[1].toLowerCase() : 'warm',
    reasoning: 'Parsed from AI response - ' + content.substring(0, 100),
    recommended_action: 'within_24h'
  };
}

// Validate score range
let score = parsed.lead_score || 50;
if (score < 0) score = 0;
if (score > 100) score = 100;

// Map priority to standard values
let priority = (parsed.priority || 'warm').toLowerCase();
if (!['hot', 'warm', 'cold'].includes(priority)) {
  priority = score >= 70 ? 'hot' : score >= 40 ? 'warm' : 'cold';
}

// Map action to standard values  
let action = (parsed.recommended_action || 'within_24h').toLowerCase();
if (!['immediate', 'within_24h', 'within_week'].includes(action)) {
  action = score >= 80 ? 'immediate' : score >= 50 ? 'within_24h' : 'within_week';
}

const webhookData = $('New Lead Webhook').item.json.body || {};

return {
  json: {
    lead_id: webhookData.lead_id || webhookData.id || $now,
    name: webhookData.name,
    email: webhookData.email,
    phone: webhookData.phone,
    property_type: webhookData.property_type,
    budget: webhookData.budget,
    timeline: webhookData.timeline,
    source: webhookData.source,
    message: webhookData.message,
    lead_score: score,
    priority: priority,
    reasoning: parsed.reasoning || 'Lead scored by AI',
    recommended_action: action,
    scored_at: $now
  }
};

